                    drop(plan);
                    drop(owner);
                })
            })
        };
        let (((), old), refused, old_paid, first) = run(true);
        assert!(!refused && first.is_none() && !old.invalid);
        assert!(old.allocated <= old_paid && old.highwater <= old_paid);
