                        drop(retry);
                        drop(error);
                        drop(pending);
                        drop(payer);
                        return (false, before_work);
                    }
                }
            }
            let used_work = work.used;
            drop(pending);
            drop(payer);
            (true, used_work)
        })
    })
}

