        units: usize,
        phase: &str,
    ) -> Result<(), Diagnostic> {
        if self.failed {
            return Err(replay_error(
                function,
                "selected preparation already failed",
            ));
        }
        let answer = self.budget.charge(function, units, phase);
        self.failed = answer.is_err();
        answer
    }
    #[cfg(test)]
    pub(crate) fn reserve_array<T>(
        &mut self,
