            .case_fields(&DeclarationId::new("choice.left"))
            .unwrap()
            .is_empty());
        drop(old);
        drop(current);
        drop(facts);
    });
    assert!(!complete.invalid);
    assert_eq!(complete.live, 0);
    assert_eq!(complete.allocated, complete.freed);
}

