    if crate::vec_ops::field_update::uses(program) {
        prelude::SCHEMA_V19
    } else if crate::vec_ops::field_unique::uses(program) {
        prelude::SCHEMA_V18
    } else if crate::vec_ops::string_slot::resolved_uses(program) {
        prelude::SCHEMA_V17
