                if let Some(item) = arms.get(*arm) {
                    if *guard {
                        *guard = false;
                        if let Some(value) = &item.guard {
                            return Some(value);
                        }
                    }
                    *arm += 1;
                    *guard = true;
                    return Some(&item.value);
                }
                None
            }
