    let identity = backing(11);
    let report = report_bytes();
    for input in [&owned, &borrowed] {
        // Second identity one short, then at zero remaining.
        assert_refusal(
            input,
            &program.path,
            report + 2 * identity - 1,
            report + identity,
            identity,
            identity - 1,
        );
        assert_refusal(
            input,
            &program.path,
            report + identity,
            report + identity,
            identity,
            0,
        );
        // Exactly two funded: the fitting larger budget reaches the function.
        assert_refusal(
